{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.RTS_ALLOCATABILITY as WITH base_raw AS ( SELECT UPPER(TRIM(SKU)) AS sku_group, REGEXP_REPLACE(UPPER(TRIM(SKU)), \'-[^-]+$\', \'\') AS sku_code, REGEXP_SUBSTR(UPPER(TRIM(SKU)), \'[^-]+$\') AS colour_code, vendor AS vendor_name, warehouse, online_qty, REPLACE(\"Logic PO\", \' \', \'\') AS logic_po, date_of_entry, delivey_Date, \"Date to allot \" AS planned_month FROM snitch_db.maplemonk.online_goods_main WHERE delivey_Date IS NULL and sku_group is not null ), meta_mapping AS ( SELECT sku_group, l1_category, category, meta1, meta2, meta3 FROM snitch_db.maplemonk.meta_mapping_cogs_sku ), base AS ( SELECT sku_group, sku_code, colour_code, vendor_name, warehouse, TRY_TO_NUMBER(REPLACE(TRIM(online_qty), \',\', \'\')) AS online_qty, logic_po, date_of_entry, CASE WHEN warehouse ILIKE \'Yelahanka-2\' THEN TRY_TO_NUMBER(REPLACE(TRIM(online_qty), \',\', \'\')) ELSE 0 END AS south_qty, CASE WHEN warehouse ILIKE \'North\' THEN TRY_TO_NUMBER(REPLACE(TRIM(online_qty), \',\', \'\')) ELSE 0 END AS north_qty, CASE WHEN warehouse ILIKE \'Yelahanka-2\' OR warehouse ILIKE \'North\' THEN TRY_TO_NUMBER(REPLACE(TRIM(online_qty), \',\', \'\')) ELSE 0 END AS total_qty, CASE WHEN date_of_entry IS NOT NULL THEN 1 ELSE 0 END AS has_date_of_entry, CASE WHEN warehouse ILIKE \'Yelahanka-2\' THEN logic_po END AS south_po, CASE WHEN warehouse ILIKE \'North\' THEN logic_po END AS north_po, CASE WHEN warehouse ILIKE \'Yelahanka-2\' THEN TO_VARCHAR(date_of_entry) END AS inspection_date_south, CASE WHEN warehouse ILIKE \'North\' THEN TO_VARCHAR(date_of_entry) END AS inspection_date_north, UPPER(TRIM(planned_month)) AS planned_month FROM base_raw ), repeat_remarks AS ( SELECT CASE WHEN REGEXP_LIKE( UPPER(TRIM(sku_group)), \'^[A-Z0-9]+-[0-9]{1}\s+.*\' ) THEN REGEXP_REPLACE( REGEXP_SUBSTR(UPPER(TRIM(sku_group)), \'^[A-Z0-9]+-[0-9]{1}\'), \'-([0-9])$\', \'-0\\1\' ) WHEN UPPER(TRIM(sku_group)) LIKE \'SN%\' OR UPPER(TRIM(sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(sku_group)) WHEN UPPER(TRIM(sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END AS sku_group, SUM(gross_quantity) AS gross_qty, \'Repeat\' AS repeat_remarks FROM snitch_db.maplemonk.horizontal_sales_categories GROUP BY 1 HAVING SUM(gross_quantity) > 0 ), photoshoot_dedup AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, MAX(shoot_date) AS shoot_date, MAX(sample_received_date) AS sample_received_date FROM snitch_db.maplemonk.sku_group_sample_to_live GROUP BY UPPER(TRIM(sku_group)) ), po_base AS ( SELECT REGEXP_REPLACE( CASE WHEN REGEXP_LIKE(UPPER(TRIM(sku_group)), \'^MP[A-Z]{2}[0-9]\') AND NOT REGEXP_LIKE(UPPER(TRIM(sku_group)), \'^MP-\') THEN \'MP-\' || SUBSTR(UPPER(TRIM(sku_group)), 3) WHEN REGEXP_LIKE(UPPER(TRIM(sku_group)), \'.*-[0-9]$\') THEN REGEXP_REPLACE(UPPER(TRIM(sku_group)), \'-([0-9])$\', \'-0\\1\') ELSE UPPER(TRIM(sku_group)) END, \'-[^-]+$\', \'\' ) AS sku_code, REGEXP_SUBSTR( CASE WHEN REGEXP_LIKE(UPPER(TRIM(sku_group)), \'^MP[A-Z]{2}[0-9]\') AND NOT REGEXP_LIKE(UPPER(TRIM(sku_group)), \'^MP-\') THEN \'MP-\' || SUBSTR(UPPER(TRIM(sku_group)), 3) WHEN REGEXP_LIKE(UPPER(TRIM(sku_group)), \'.*-[0-9]$\') THEN REGEXP_REPLACE(UPPER(TRIM(sku_group)), \'-([0-9])$\', \'-0\\1\') ELSE UPPER(TRIM(sku_group)) END, \'[^-]+$\' ) AS colour_code FROM snitch_db.maplemonk.logic_purchase_order WHERE sku_group LIKE \'%-%\' ), collection_dedup AS ( SELECT CASE WHEN REGEXP_LIKE(UPPER(TRIM(sku)), \'^MP[A-Z]{2}[0-9]\') AND NOT REGEXP_LIKE(UPPER(TRIM(sku)), \'^MP-\') THEN \'MP-\' || SUBSTR(UPPER(TRIM(sku)), 3) WHEN REGEXP_LIKE(UPPER(TRIM(sku)), \'.*-[0-9]$\') THEN REGEXP_REPLACE(UPPER(TRIM(sku)), \'-([0-9])$\', \'-0\\1\') ELSE UPPER(TRIM(sku)) END AS sku_group, ANY_VALUE(collection) AS collection FROM snitch_db.maplemonk.collection_sku_mapped GROUP BY 1 ), sku_class AS ( SELECT CASE WHEN REGEXP_LIKE(UPPER(TRIM(sku_group)), \'^MP[A-Z]{2}[0-9]\') AND NOT REGEXP_LIKE(UPPER(TRIM(sku_group)), \'^MP-\') THEN \'MP-\' || SUBSTR(UPPER(TRIM(sku_group)), 3) WHEN REGEXP_LIKE(UPPER(TRIM(sku_group)), \'.*-[0-9]$\') THEN REGEXP_REPLACE(UPPER(TRIM(sku_group)), \'-([0-9])$\', \'-0\\1\') ELSE UPPER(TRIM(sku_group)) END AS sku_group, ANY_VALUE(sku_class) AS sku_class FROM snitch_db.maplemonk.availability_master_v2 GROUP BY 1 ), collection_count AS ( SELECT collection, COUNT(DISTINCT CASE WHEN REGEXP_LIKE(UPPER(TRIM(sku)), \'^MP[A-Z]{2}[0-9]\') AND NOT REGEXP_LIKE(UPPER(TRIM(sku)), \'^MP-\') THEN \'MP-\' || SUBSTR(UPPER(TRIM(sku)), 3) WHEN REGEXP_LIKE(UPPER(TRIM(sku)), \'.*-[0-9]$\') THEN REGEXP_REPLACE(UPPER(TRIM(sku)), \'-([0-9])$\', \'-0\\1\') ELSE UPPER(TRIM(sku)) END ) AS collection_count FROM snitch_db.maplemonk.collection_sku_mapped GROUP BY collection ), po_sku_colours AS ( SELECT sku_code, COUNT(DISTINCT colour_code) AS po_colours FROM po_base GROUP BY sku_code ), final_base AS ( SELECT b.sku_group, b.sku_code, b.colour_code, B.WAREHOUSE, mm.l1_category, mm.category, mm.meta1, mm.meta2, mm.meta3, sc.sku_class, rr.repeat_remarks, b.vendor_name, b.south_qty, b.north_qty, b.total_qty, b.south_po, b.north_po, b.inspection_date_north, b.inspection_date_south, b.planned_month, cd.collection, cc.collection_count, CASE WHEN cd.collection IS NOT NULL THEN COUNT(DISTINCT b.sku_group) OVER (PARTITION BY cd.collection) END AS collection_present, pd.shoot_date, pd.sample_received_date, pc.po_colours, COUNT(DISTINCT CASE WHEN b.has_date_of_entry = 1 THEN b.colour_code END) OVER (PARTITION BY b.sku_code) AS colour_count FROM base b LEFT JOIN photoshoot_dedup pd ON b.sku_group = pd.sku_group LEFT JOIN po_sku_colours pc ON pc.sku_code = b.sku_code LEFT JOIN collection_dedup cd ON cd.sku_group = b.sku_group LEFT JOIN sku_class sc ON sc.sku_group = b.sku_group LEFT JOIN repeat_remarks rr ON UPPER(TRIM(rr.sku_group)) = UPPER(TRIM(b.sku_group)) LEFT JOIN collection_count cc ON cc.collection = cd.collection LEFT JOIN meta_mapping mm ON b.sku_group = mm.sku_group ), final_with_remarks AS ( SELECT *, CASE WHEN LOWER(category) = \'jeans\' THEN \'JEANS\' WHEN po_colours = colour_count THEN \'COLOURS-READY\' WHEN po_colours > colour_count THEN \'COLOURS-PENDING\' ELSE \'PO-ISSUE\' END AS colour_remarks, CASE WHEN repeat_remarks ilike \'Repeat\' THEN\'Repeat\' WHEN shoot_date IS NULL AND sample_received_date IS NOT NULL AND CURRENT_DATE > DATEADD(day, 3, sample_received_date) THEN \'PHOTOSHOOT - PASS\' WHEN shoot_date IS NULL AND sample_received_date IS NOT NULL THEN \'SAMPLE - RECEIVED\' WHEN sample_received_date IS NULL THEN \'SAMPLE - NOT RECEIVED\' WHEN shoot_date IS NOT NULL THEN \'PHOTOSHOOT - DONE\' END AS photoshoot_remarks, CASE WHEN planned_month ILIKE \'APRIL%\' THEN \'APRIL PLANNED\' WHEN planned_month ILIKE \'MAY%\' THEN \'MAY PLANNED\' WHEN planned_month ILIKE \'#N/A\' THEN \'NOT IN PLANNED\' END AS planned_month_remarks, CASE WHEN collection_count = collection_present THEN \'COLLECTION - READY\' WHEN collection_count > collection_present THEN \'COLLECTION - PENDING\' ELSE NULL END AS collection_remarks FROM final_base ), final_output AS ( SELECT *, CASE WHEN repeat_remarks = \'Repeat\' AND photoshoot_remarks ilike \'Repeat\' THEN \'ALLOCATABLE\' WHEN sku_group ilike \'MP-%\' and photoshoot_remarks in( \'PHOTOSHOOT - PASS\',\'PHOTOSHOOT - DONE\') THEN \'ALLOCATABLE\' WHEN SKU_GROUP ILIKE \'MP-%\' AND photoshoot_remarks not in ( \'PHOTOSHOOT - PASS\',\'PHOTOSHOOT - DONE\') THEN \'NON-ALLOCATABLE\' WHEN colour_remarks ILIKE \'COLOURS-READY\' AND photoshoot_remarks IN (\'PHOTOSHOOT - DONE\', \'PHOTOSHOOT - PASS\') AND planned_month_remarks ILIKE \'MAY PLANNED\' AND (collection_remarks IS NULL OR collection_remarks ILIKE \'COLLECTION - READY\') THEN \'ALLOCATABLE\' WHEN LOWER(category) = \'jeans\' and photoshoot_remarks in (\'PHOTOSHOOT - DONE\',\'PHOTOSHOOT - PASS\') and planned_month_remarks IN( \'MAY PLANNED\',\'APRIL PLANNED\') THEN \'ALLOCATABLE\' WHEN colour_remarks ILIKE \'COLOURS-READY\' AND photoshoot_remarks IN (\'PHOTOSHOOT - DONE\', \'PHOTOSHOOT - PASS\') AND planned_month_remarks ILIKE \'APRIL PLANNED\' AND collection_remarks IS NULL THEN \'ALLOCATABLE\' WHEN LOWER(category) = \'jeans\' AND photoshoot_remarks NOT IN (\'PHOTOSHOOT - PASS\',\'PHOTOSHOOT - DONE\') and planned_month NOT IN (\'MAY PLANNED\',\'APRIL PLANNED\') THEN \'NON-ALLOCATABLE\' WHEN colour_remarks ILIKE \'COLOURS-READY\' AND photoshoot_remarks IN (\'PHOTOSHOOT - DONE\', \'PHOTOSHOOT - PASS\') AND planned_month_remarks ILIKE \'NOT IN PLANNED\' THEN \'NON-ALLOCATABLE\' ELSE \'NON-ALLOCATABLE\' END AS final_remarks FROM final_with_remarks ) SELECT *, CASE WHEN sku_group ilike \'MP-%\' and final_remarks = \'ALLOCATABLE\' THEN \'MP SKU\' WHEN final_remarks = \'ALLOCATABLE\' AND repeat_remarks = \'Repeat\' THEN \'REPEAT\' WHEN final_remarks = \'ALLOCATABLE\' AND LOWER(category) = \'jeans\' THEN \'JEANS\' WHEN final_remarks = \'ALLOCATABLE\' AND collection IS NOT NULL THEN \'COLLECTION\' WHEN final_remarks = \'ALLOCATABLE\' and repeat_remarks is null THEN \'NEW\' WHEN colour_remarks ILIKE \'ALLOCATABLE\' AND planned_month_remarks ILIKE \'APRIL PLANNED\' THEN \'APRIL PLANNED\' WHEN final_remarks = \'NON-ALLOCATABLE\' AND colour_remarks = \'COLOURS-PENDING\' THEN \'COLOURS PENDING\' WHEN final_remarks = \'NON-ALLOCATABLE\' AND photoshoot_remarks IN (\'SAMPLE - RECEIVED\', \'SAMPLE - NOT RECEIVED\') THEN \'PHOTOSHOOT PENDING\' WHEN final_remarks = \'NON-ALLOCATABLE\' AND planned_month_remarks NOT IN (\'MAY PLANNED\', \'APRIL PLANNED\') THEN \'NOT PLANNED\' WHEN final_remarks = \'NON-ALLOCATABLE\' AND collection_remarks = \'COLLECTION - PENDING\' THEN \'COLLECTION PENDING\' ELSE NULL END AS final_breakdown FROM final_output;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            